576	__device__ __forceinline__ void rescale_o_g(float (&acc_o)[N], const float* sc) {
577	#pragma unroll
578	    for (int c = 0; c < N / 4; ++c) {
579	        acc_o[c*4+0] *= sc[0]; acc_o[c*4+1] *= sc[0];
