280	        if (k0     >= seqlen_k || (causal && k0     > qhi)) s[c*4+2] = -INFINITY;
281	        if (k0 + 1 >= seqlen_k || (causal && k0 + 1 > qhi)) s[c*4+3] = -INFINITY;
282	    }
283	}
