22	__device__ __forceinline__ void thread_reduce_(Tensor<Engine0, Layout0> const &tensor, Tensor<Engine1, Layout1> &summary, Operator &op) {
23	    static_assert(Layout0::rank == 2, "Only support 2D Tensor");
24	    static_assert(Layout1::rank == 1, "Only support 1D Tensor");
25	    CUTE_STATIC_ASSERT_V(size<0>(summary) == size<0>(tensor));
26	    #pragma unroll
27	    for (int ni = 0; ni < size<1>(tensor); ni++) {
28	        #pragma unroll
29	        for (int mi = 0; mi < size<0>(tensor); mi++) {
30	            summary(mi) = zero_init && ni == 0 ? tensor(mi, ni) : op(summary(mi), tensor(mi, ni));
31	        }
32	    }
33	}
